equation_logic_text:
var age = age || 0;
var ldl = ldl || 0;
var age2 = age2 || 0;
var diabetes = diabetes || 0;
var sex = sex || 0;
var race = race || 0;
var smoker = smoker || 0;
var chol_total = chol_total || 0;
var chol_hdl = chol_hdl || 0;
var sbp = sbp || 0;
var bptreated = bptreated || 0;

var msg;

var calc_output = [];
// baseline variables, no natural logs
age = parseFloat(age);
ldl = parseFloat(ldl);
age2 = parseFloat(age2);
diabetes = parseFloat(diabetes);
sex = parseFloat(sex);
race = parseFloat(race);
smoker = parseFloat(smoker);
sbp = parseFloat(sbp);
bptreated = parseFloat(bptreated);

var ascvd = parseFloat(ascvd);

if (UOMSYSTEM == true) {
  // US units, so let'em through
  var cholesterol = parseFloat(chol_total);
  var hdl = parseFloat(chol_hdl);
}
if (UOMSYSTEM == false) {
  // convert these guys to US units
  var cholesterol = parseFloat(chol_total) / 0.0259;
  var hdl = parseFloat(chol_hdl) / 0.0259;
}

var statin_add_high =
  "<br/><br/>To view statin dosages by intensity, see Evidence section.";
var statin_add_high_moderate =
  "<br/><br/>To view statin dosages by intensity, see Evidence section.";

var statin_add_moderate =
  "<br/><br/>To view statin dosages by intensity, see Evidence section.";
var statin_add_low =
  "<br/><br/>To view statin dosages by intensity, see Evidence section.";

var rec = "";
var mini_rec = "";

if (ascvd == 1) {
  // if they have ASCVD you can hide everything else, 'cuz they need some statin

  if (age > 0) {
    if (age < 21) {
      rec = "Age must be ≥21.";
      mini_rec = "Age must be ≥21.";
      s = "N/A";
    } else {
      if (age > 75) {
        rec =
          "Moderate-intensity statin recommended because of known ASCVD and age >75." +
          statin_add_moderate;
        mini_rec = "Moderate-intensity statin recommended...";
        s = "N/A";
      }

      if (age <= 75) {
        rec =
          "High-intensity statin recommended; if not tolerated or not a candidate, moderate-intensity recommended because of known ASCVD and age ≤75." +
          statin_add_high;
        mini_rec = "High-intensity statin recommended...";
        s = "N/A";
      }
    } // END AGE < 21
  } // END < 0
} // END if ASCVD==1
else {
  //if (ascvd == 0) {
  //    mdcSetPointsText("#res1", ""); // set blank since everything's optional and the calc will automatically result
  //
  //    // show the LDL question if q1 is No
  //    mdcShow('#ldl');
  //    $('#header_step2').show();
  //}

  if (ldl == 1) {
    // if they have high LDL you can hide everything else including age 'cuz they need some statin

    rec =
      "High-intensity statin recommended; if not tolerated or not a candidate, moderate-intensity recommended because of extreme LDL level but no known ASCVD." +
      statin_add_high;
    mini_rec = "High-intensity statin recommended...";
    s = "N/A";
  } // END if HIGH LDL
  else {
    if (ldl == 0) {
      // go ahead and do the ASCVD calculation then

      //calculator variables
      var e = 2.718281828;
      var index;
      var s;
      var sum;
      var mean;

      if (cholesterol > 0 && hdl > 0 && sbp > 0) {
        // set natural log elements
        var lnage = Math.log(age2);
        var lncholesterol = Math.log(cholesterol);
        var lnhdl = Math.log(hdl);
        var lnsbp = Math.log(sbp);
        var lnageage = lnage * lnage;
        var lnagetotal = lnage * lncholesterol;
        var lnagehdl = lnage * lnhdl;
        var lnagesbp = lnage * lnsbp;
        var lnagesmoker = lnage * smoker;

        // if male

        if (sex == 1) {
          if (race == 1 || race == 3) {
            lnage = lnage * 12.344;
            lncholesterol = lncholesterol * 11.853;
            lnagetotal = lnagetotal * -2.664;
            lnhdl = lnhdl * -7.99;
            lnagehdl = 1.769 * lnagehdl;
            if (bptreated == 1) {
              lnsbp = lnsbp * 1.797;
            } else {
              lnsbp = lnsbp * 1.764;
            }
            smoker = smoker * 7.837;
            lnagesmoker = lnagesmoker * -1.795;
            diabetes = diabetes * 0.658;
            sum =
              lnage +
              lncholesterol +
              lnagetotal +
              lnhdl +
              lnagehdl +
              lnsbp +
              lnagesmoker +
              smoker +
              diabetes;
            mean = 61.1816;
            index = sum - mean;
            s = (100 * (1 - Math.pow(0.91436, Math.exp(index)))).toFixed(1);
          }
          if (race == 2) {
            lnage = lnage * 2.469;
            lncholesterol = lncholesterol * 0.302;
            lnhdl = lnhdl * -0.307;
            if (bptreated == 1) {
              lnsbp = lnsbp * 1.916;
            } else {
              lnsbp = lnsbp * 1.809;
            }
            smoker = smoker * 0.549;
            diabetes = diabetes * 0.645;
            sum = lnage + lncholesterol + lnhdl + lnsbp + smoker + diabetes;
            mean = 19.5425;
            index = sum - mean;
            s = (100 * (1 - Math.pow(0.89536, Math.exp(index)))).toFixed(1);
          }
        }

        //if female

        if (sex == 0) {
          if (race == 1 || race == 3) {
            lnage = lnage * -29.799;
            lnageage = lnageage * 4.884;
            lncholesterol = lncholesterol * 13.54;
            lnagetotal = lnagetotal * -3.114;
            lnhdl = lnhdl * -13.578;
            lnagehdl = lnagehdl * 3.149;
            if (bptreated == 1) {
              lnsbp = lnsbp * 2.019;
            } else {
              lnsbp = lnsbp * 1.957;
            }
            smoker = smoker * 7.574;
            lnagesmoker = lnagesmoker * -1.665;
            diabetes = diabetes * 0.661;
            sum =
              lnage +
              lnageage +
              lncholesterol +
              lnagetotal +
              lnhdl +
              lnagehdl +
              lnsbp +
              lnagesmoker +
              smoker +
              diabetes;
            mean = -29.1817;
            index = sum - mean;
            s = (100 * (1 - Math.pow(0.96652, Math.exp(index)))).toFixed(1);
          }
          if (race == 2) {
            lnage = lnage * 17.114;
            lncholesterol = lncholesterol * 0.94;
            lnhdl = lnhdl * -18.92;
            lnagehdl = lnagehdl * 4.475;
            if (bptreated == 1) {
              lnsbp = lnsbp * 29.291;
              lnagesbp = lnagesbp * -6.432;
            } else {
              lnsbp = lnsbp * 27.82;
              lnagesbp = lnagesbp * -6.087;
            }
            smoker = smoker * 0.691;
            diabetes = diabetes * 0.874;
            sum =
              lnage +
              lncholesterol +
              lnhdl +
              lnagehdl +
              lnsbp +
              lnagesbp +
              smoker +
              diabetes;
            mean = 86.6081;
            index = sum - mean;
            s = (100 * (1 - Math.pow(0.95334, Math.exp(index)))).toFixed(1);
          }
        }
        if (race > 0) {
          if (diabetes == 0) {
            if (age2 < 40) {
              mini_rec = "No statin recommended because age <40.";
              rec =
                "No statin recommended because age <40; always encourage healthy cardiovascular lifestyle choices. Some patients with other high risk features may still be appropriate for treatment.";
            } else if (age2 > 75) {
              mini_rec = "No statin recommended because age >75.";
              rec =
                "No statin recommended because age >75; always encourage healthy cardiovascular lifestyle choices. Some patients with other high risk features may still be appropriate for treatment.";
            } else {
              if (s < 5) {
                mini_rec = "No statin recommended because 10-year risk <5%.";
                rec =
                  "No statin recommended because 10-year risk <5%; always encourage healthy cardiovascular lifestyle choices. Some patients with other high risk features may still be appropriate for treatment.";
              }
              if (s >= 5 && s < 7.5) {
                mini_rec = "Moderate-intensity statin recommended.";
                rec =
                  "Moderate-intensity statin recommended because of 10-year risk between 5-7.5%." +
                  statin_add_moderate;
              }
              if (s >= 7.5 && s <= 10) {
                mini_rec = "Moderate- to high-intensity statin recommended.";
                rec =
                  "Moderate- to high-intensity statin recommended because 10-year risk >7.5% <br><br> ACC/AHA recommends initiating statins at this risk level, but the USPSTF recommends a trial of lifestyle intervention first - use clinician judgment and shared decision making in deciding whether or not to start a statin" +
                  statin_add_high_moderate;
              } else if (s > 10) {
                mini_rec = "Moderate- to high-intensity statin recommended.";
                rec =
                  "Moderate- to high-intensity statin recommended because 10-year risk >7.5%" +
                  statin_add_high_moderate;
              }
            }
          } else {
            if (age2 < 40 || age2 > 75) {
              rec =
                "In diabetic patients ages <40 or >75, consider additional factors like lifestyle and risk-benefits before starting statins.";
              mini_rec =
                "In diabetic patients ages <40 or >75, consider additional factors before starting statins.";
            } else {
              if (s >= 7.5 && s <= 10) {
                mini_rec = "High-intensity statin recommended.";
                rec =
                  "High-intensity statin recommended because of known diabetes and 10-year risk >7.5%.<br/><br/> If LDL <70mg/dl (1.81 mmol/L), additional factors like lifestyle and risk-benefits can be considered before starting statins <br><br> ACC/AHA recommends initiating statins at this risk level, but the USPSTF recommends a trial of lifestyle intervention first - use clinician judgment and shared decision making in deciding whether or not to start a statin" +
                  statin_add_high;
              }
              if (s > 10) {
                mini_rec = "High-intensity statin recommended.";
                rec =
                  "High-intensity statin recommended because of known diabetes and 10-year risk >7.5%.<br/><br/> If LDL <70mg/dl (1.81 mmol/L), additional factors like lifestyle and risk-benefits can be considered before starting statins" +
                  statin_add_high;
              }
              if (s < 7.5) {
                mini_rec = "Moderate-intensity statin recommended.";
                rec =
                  "Moderate-intensity statin recommended because of known diabetes but 10-year risk <7.5%.<br/><br/> If LDL <70mg/dl (1.81 mmol/L), additional factors like lifestyle and risk-benefits can be considered before starting statins." +
                  statin_add_moderate;
              }
            }
          }

          msg =
            "Risk of cardiovascular event (coronary or stroke death or non-fatal MI or stroke) in next 10 years.";
          if (race == 3) {
            msg +=
              "<br/><br/>Note: These estimates may underestimate or overestimate the 10-year risk for some race/ethnic groups. See Evidence section for more information.";
          }
        }

          msg =
            "Risk of cardiovascular event (coronary or stroke death or non-fatal MI or stroke) in next 10 years.";
          if (race == 3) {
            msg +=
              "<br/><br/>Note: These estimates may underestimate or overestimate the 10-year risk for some race/ethnic groups. See Evidence section for more information.";
          }
        }
      }
    }
  }
if (race > 0) {
  calc_output.push({
    name: "mini",
    value: " ",
    value_text: " ",
    message: mini_rec,
  });
  if (ascvd == 0 && ldl == 0) {
    calc_output.push({
      name: "3400_ASCVD Risk Algorithm_result (risk)",
      value: s,
      value_text: "%",
      message: msg,
    });
  }
  calc_output.push({
    name: "3400_ASCVD Risk Algorithm_result (rec)",
    value: "",
    value_text: "",
    message: rec,
  });
}
if (race == 0) {
  calc_output.push({
    name: "mini",
    value: " ",
    value_text: " ",
    message: mini_rec,
  });
  if (ascvd == 0 && ldl == 0) {
    calc_output.push({
      name: "3400_ASCVD Risk Algorithm_result (risk)",
      value: s1 + "-" + s2,
      value_text: "%",
      message: msg,
    });
  }
  calc_output.push({
    name: "3400_ASCVD Risk Algorithm_result (rec)",
    value: "",
    value_text: "",
    message: rec,
  });
}
